class TestPointerOverRow:
    """Guard used both before display and while a tooltip is up."""

    def test_pointer_on_visible_row(self):
        win = _make_window(pointer_xy=(300, 210))
        assert win._pointer_over_row(_make_widget()) is True

    def test_pointer_away_from_row(self):
        win = _make_window(pointer_xy=(4000, 4000))
        assert win._pointer_over_row(_make_widget()) is False

    def test_hidden_window_never_matches(self):
        win = _make_window(pointer_xy=(300, 210))
        win._window.winfo_viewable.return_value = 0
