class TestWatchPointer:
    def test_pointer_off_row_hides_tooltip(self):
        win = _make_window(pointer_xy=(4000, 4000))
        tip = win._tooltip_window
        win._watch_pointer(_make_widget())
        tip.destroy.assert_called_once()
        assert win._tooltip_window is None
        assert win._tooltip_watch_id is None

    def test_pointer_on_row_reschedules(self):
        win = _make_window(pointer_xy=(300, 210))
        win._watch_pointer(_make_widget())
        assert win._tooltip_window is not None
        assert win._tooltip_watch_id == "after#1"

    def test_destroyed_row_hides_tooltip(self):
        win = _make_window(pointer_xy=(300, 210))
        widget = _make_widget()
        widget.winfo_rootx.side_effect = tk.TclError("bad window path name")
        tip = win._tooltip_window
        win._watch_pointer(widget)
        tip.destroy.assert_called_once()
        assert win._tooltip_window is None

    def test_no_tooltip_stops_polling(self):
        win = _make_window(pointer_xy=(300, 210))
        win._tooltip_window = None
        win._watch_pointer(_make_widget())
        win._window.after.assert_not_called()
        assert win._tooltip_watch_id is None


class TestReArmGuard:
    """A synthetic <Enter> after unmapping must not restart the tooltip."""

    def test_ignores_repeat_while_shown(self):
        win = _make_window(pointer_xy=(300, 210))
        win._show_tooltip(MagicMock(), 1000)
        win._window.after.assert_not_called()
        assert win._tooltip_window is not None

    def test_ignores_repeat_while_pending(self):
        win = _make_window(pointer_xy=(300, 210))
        win._tooltip_window = None
        win._tooltip_after_id = "after#3"
        win._show_tooltip(MagicMock(), 1000)
        win._window.after.assert_not_called()
        assert win._tooltip_after_id == "after#3"

    def test_other_row_replaces_tooltip(self):
        win = _make_window(pointer_xy=(300, 210))
        win._settings = MagicMock(tooltip_delay_ms=500)
        tip = win._tooltip_window
        win._show_tooltip(MagicMock(), 2000)
        tip.destroy.assert_called_once()
        assert win._tooltip_pid == 2000
        assert win._tooltip_after_id == "after#1"


class TestHideCancelsTimers:
    def test_all_three_timers_cancelled(self):
        win = _make_window(pointer_xy=(300, 210))
        win._tooltip_after_id = "after#3"
        win._hide_tooltip()
        cancelled = {call.args[0] for call in win._window.after_cancel.call_args_list}
